#include "SpiHelper.h"
#include <avr/io.h>

#define SPI_HELPER_TIMEOUT_LOOPS 500U

bool Spi0Helper_BufferExchange(uint8_t *buffer, size_t size) {
  for (size_t i = 0; i < size; i++) {
    SPI0.DATA = buffer[i];
    uint16_t timeout = SPI_HELPER_TIMEOUT_LOOPS;
    while ((SPI0.INTFLAGS & SPI_RXCIF_bm) == 0U) {
      if (--timeout == 0U) {
        return false;
      }
    }
    buffer[i] = SPI0.DATA;
  }
  return true;
}